INSERT INTO users(id,email,name) VALUES(1,'editorial@example.invalid','فريق تنميات');
INSERT INTO posts(author_id,topic,title,body) VALUES
(1,'التعليم','مكتبة الحي التي يشارك الجميع في اختيار كتبها','تبدأ الفكرة بسؤال الأهالي والطلاب عن الكتب التي يودّون قراءتها. تُعرض المقترحات في لقاء شهري، ثم تختار المكتبة مجموعة صغيرة للتجربة. ويمكن قياس أثر المبادرة بعدد الكتب التي عادت إلى التداول وعدد القرّاء الذين شاركوا للمرة الأولى.'),
(1,'البيئة','كيف نختار موقع حديقة مجتمعية؟','قبل اختيار الموقع، يمكن رسم مسارات المشاة وتحديد الأحياء التي تفتقر إلى مساحات ظلّ وجلوس. زيارة المواقع المقترحة مع السكان تكشف تفاصيل يصعب رصدها على الخريطة، مثل سهولة الوصول لكبار السن وتوافر المياه لريّ النباتات.'),
(1,'المجتمع','ماذا يخبرنا المستفيدون بعد انتهاء المبادرة؟','قد ينجح يوم النشاط في جذب المشاركين، لكن المتابعة بعد شهر تكشف جانبًا آخر من الأثر. نسأل المشاركين عمّا استخدموه في حياتهم اليومية، وما تعذّر تطبيقه، وأي تعديل يجعل التجربة أنفع في الدورة القادمة.');
